1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.AgeBand;
8	import org.springframework.samples.petclinic.model.CheckDigit;
9	import org.springframework.samples.petclinic.model.CustomerCode;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.model.OwnerIdentity;
12	import org.springframework.samples.petclinic.model.Tenure;
13	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
14	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
15	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
16	import org.springframework.samples.petclinic.rest.function.owner.OwnerTelephones;
17	
18	import java.util.Collection;
19	import java.util.List;
20	
21	/**
22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
28	    @Mapping(target = "initials", expression = "java(initials(owner))")
29	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
30	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
31	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
32	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
33	    @Mapping(target = "locality", expression = "java(locality(owner))")
34	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
35	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
36	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
37	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
38	    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
39	    OwnerDto toOwnerDto(Owner owner);
40	
41	    Owner toOwner(OwnerDto ownerDto);
42	
43	    /** Format an owner's name as 'LastName, FirstName' for display. */
44	    default String displayName(Owner owner) {
45	        return owner.getLastName() + ", " + owner.getFirstName();
46	    }
47	
48	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
49	    default String initials(Owner owner) {
50	        return initial(owner.getFirstName()) + initial(owner.getLastName());
51	    }
52	
53	    /** The stored E.164 telephone formatted for humans (see {@link OwnerTelephones#toDisplay}). */
54	    default String telephoneDisplay(Owner owner) {
55	        return OwnerTelephones.toDisplay(owner.getTelephone());
56	    }
57	
58	    private static String initial(String name) {
59	        return Character.toUpperCase(name.charAt(0)) + ".";
60	    }
61	
62	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
63	     * last two digits of the registrationDate year. */
64	    default String membershipNumber(Owner owner) {
65	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
66	            return null;
67	        }
68	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
69	    }
70	
71	    /** The owner's membership points: starts at 0, plus 2 when an email is present, plus 1 when
72	     * namesakeCount is 0, plus 2 for a household of 3 or more, plus 3 when tenure exceeds 365 days. */
73	    default int membershipPoints(Owner owner) {
74	        int points = 0;
75	        if (hasEmail(owner)) {
76	            points += 2;
77	        }
78	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
79	            points += 1;
80	        }
81	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
82	            points += 2;
83	        }
84	        if (Tenure.days(owner.getRegistrationDate()) > 365) {
85	            points += 3;
86	        }
87	        return points;
88	    }
89	
90	    /** The owner's membership level from 1 to 4, derived from {@link #membershipPoints(Owner)}:
91	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more. */
92	    default int membershipLevel(Owner owner) {
93	        int points = membershipPoints(owner);
94	        if (points <= 1) {
95	            return 1;
96	        }
97	        if (points <= 3) {
98	            return 2;
99	        }
100	        if (points <= 5) {
101	            return 3;
102	        }
103	        return 4;
104	    }
105	
106	    /** The owner's canonical region: the REGION segment of the customer code (see
107	     * {@link CustomerCode}), or null when the customer code is unset. */
108	    default String locality(Owner owner) {
109	        return CustomerCode.region(owner.getCustomerCode());
110	    }
111	
112	    /** The owner's preferred contact channel: 'EMAIL' when an email is present, otherwise 'PHONE'. */
113	    default String contactPreference(Owner owner) {
114	        return hasEmail(owner) ? "EMAIL" : "PHONE";
115	    }
116	
117	    /** Whether the owner has a non-blank email. */
118	    private static boolean hasEmail(Owner owner) {
119	        return owner.getEmail() != null && !owner.getEmail().isBlank();
120	    }
121	
122	    /** The owner's derived identity key (see {@link OwnerIdentity}). */
123	    default String identityKey(Owner owner) {
124	        return OwnerIdentity.of(owner);
125	    }
126	
127	    /** The Luhn check digit over the digits of the owner's customer code, or null when unset. */
128	    default Integer checkDigit(Owner owner) {
129	        return owner.getCustomerCode() == null ? null : CheckDigit.luhn(owner.getCustomerCode());
130	    }
131	
132	    /** The owner's age band on their registration date, derived from their birth date (see
133	     * {@link AgeBand}), or null when either date is unset. */
134	    default String ageBand(Owner owner) {
135	        return AgeBand.on(owner.getBirthDate(), owner.getRegistrationDate());
136	    }
137	
138	    /** Whether the owner soft-matched an existing owner at creation, i.e. it has a
139	     * {@code possibleDuplicateOf} id. */
140	    default boolean possibleDuplicate(Owner owner) {
141	        return owner.getPossibleDuplicateOf() != null;
142	    }
143	
144	    @Mapping(target = "id", ignore = true)
145	    @Mapping(target = "pets", ignore = true)
146	    @Mapping(target = "customerCode", ignore = true)
147	    @Mapping(target = "householdId", ignore = true)
148	    @Mapping(target = "namesakeCount", ignore = true)
149	    @Mapping(target = "householdSize", ignore = true)
150	    @Mapping(target = "bulkSignupWarning", ignore = true)
151	    @Mapping(target = "possibleDuplicateOf", ignore = true)
152	    Owner toOwner(OwnerFieldsDto ownerDto);
153	
154	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
155	
156	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
157	
158	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
159	        OwnerPageDto ownerPageDto = new OwnerPageDto();
160	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
161	        ownerPageDto.setPage(ownerPage.getNumber());
162	        ownerPageDto.setSize(ownerPage.getSize());
163	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
164	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
165	        return ownerPageDto;
166	    }
167	}
